UPDATE inform.politician_context SET reasoning = 'Fleming has called abortion a pernicious evil" and "a national sin, co-sponsored the Life at Conception Act (2015) and the Sanctity of Human Life Act to recognize personhood from fertilization, and has sought to ban all federal funding for abortion including defunding Planned Parenthood. He does allow narrow exceptions for rape, incest, and life of the mother, which places him at 4.5 rather than a full 5.',
       sources = ARRAY['https://www.ontheissues.org/House/John_Fleming.htm', 'https://www.ontheissues.org/House/John_Fleming_Abortion.htm']::text[]
 WHERE politician_id = '8be7e981-77a6-4ef7-b8d7-891fd9cc26d8' AND topic_id = 'af2fdfd6-02c4-49df-b09c-cf8536f4773f';
-- John Fleming / Deportation
UPDATE inform.politician_context SET reasoning = 'Fleming calls unauthorized immigration an invasion by illegal aliens, supports securing the border by all means necessary, and requires all undocumented immigrants to return home and re-enter through legal channels. He supports deporting those convicted of crimes as a priority and removing all public benefits as an enforcement mechanism, though has not explicitly called for mass immediate deportation of all long-term residents.',
       sources = ARRAY['https://www.ontheissues.org/House/John_Fleming_Immigration.htm']::text[]
 WHERE politician_id = '8be7e981-77a6-4ef7-b8d7-891fd9cc26d8' AND topic_id = '44905f3b-e105-4f6c-afc7-5d223813dbac';
