       sources = ARRAY['https://marylandmatters.org/2025/03/31/senate-republicans-score-budget-win-as-spending-plan-clears-preliminary-hurdle/']::text[]
 WHERE politician_id = '9f8d0005-c5ff-42f8-b158-cdb6e4eee872' AND topic_id = 'f7e5678d-dadd-4556-a2fc-446e24642ceb';
